import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Diagnostic codes","description":"Every diagnostic code Tuimark reports, grouped by the pass that finds it.","frontmatter":{"title":"Diagnostic codes","description":"Every diagnostic code Tuimark reports, grouped by the pass that finds it.","editLink":false,"head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/reference/diagnostics"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"Diagnostic codes | Tuimark"}],["meta",{"property":"og:description","content":"Every diagnostic code Tuimark reports, grouped by the pass that finds it."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/reference/diagnostics"}],["meta",{"name":"twitter:title","content":"Diagnostic codes | Tuimark"}],["meta",{"name":"twitter:description","content":"Every diagnostic code Tuimark reports, grouped by the pass that finds it."}]]},"headers":[],"relativePath":"reference/diagnostics.md","filePath":"reference/diagnostics.md","lastUpdated":1792376055000}'),a={name:"reference/diagnostics.md"};function n(i,e,r,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="diagnostic-codes" tabindex="-1">Diagnostic codes <a class="header-anchor" href="#diagnostic-codes" aria-label="Permalink to &quot;Diagnostic codes&quot;">​</a></h1><p>Every problem Tuimark finds is a diagnostic with a stable code. The letter names the pass (<code>V</code> parse, <code>L</code> layout, <code>B</code> bind), and the dump lists each one under <code>errors</code> with its <code>severity</code>, <code>code</code>, message, and source position. A dump with any error-severity diagnostic has <code>&quot;ok&quot;: false</code>, and the CLI exits 2. Link to a code with its anchor, like <a href="#v003"><code>/reference/diagnostics#v003</code></a>.</p><h2 id="parse" tabindex="-1">Parse (<code>V…</code>) <a class="header-anchor" href="#parse" aria-label="Permalink to &quot;Parse (`V…`) {#parse}&quot;">​</a></h2><p>Reported while reading the <code>.tui</code> document and its stylesheets. Most are errors: the dump is not <code>ok</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><span id="v001"></span><code>V001</code></td><td>unknown tag; a version=&quot;2&quot; tag in a version=&quot;1&quot; document (message ends with <code>(requires version=&quot;2&quot;)</code>); <code>input</code>, <code>button</code>, <code>list</code>, <code>modal</code>, <code>table</code>, <code>tabs</code>, or <code>tab</code> inside a container <code>each</code> template</td></tr><tr><td><span id="v002"></span><code>V002</code></td><td>unknown attribute; a version=&quot;2&quot; attribute in a version=&quot;1&quot; document (with the same hint); <code>focusable</code>, <code>on:click</code>, or <code>on:focus</code> inside a container <code>each</code> template; a version=&quot;3&quot; attribute (<code>stick</code> on <code>scroll</code>, <code>focus</code> on <code>modal</code>, <code>when</code> on <code>keymap</code>, <code>priority</code> on <code>column</code>, <code>scale</code> on <code>sparkline</code>) in a version=&quot;1&quot; or version=&quot;2&quot; document, with <code>(requires version=&quot;3&quot;)</code> (on a 0.2b tag in a version=&quot;1&quot; document only that tag&#39;s V001 is reported); <code>stick</code> inside a list <code>&lt;item&gt;</code> or a container <code>each</code> template (version=&quot;3&quot;)</td></tr><tr><td><span id="v003"></span><code>V003</code></td><td>bad unit / color / token / CSS property; a <code>version</code> other than 1, 2, or 3; a version=&quot;2&quot; value, property, pseudo-class, media feature, or built-in action in a version=&quot;1&quot; document (with the hint); <code>switch-to</code> without <code>to</code>; a hyphenated built-in in an <code>on:*</code> attribute; a <code>tab</code> without a non-empty <code>label</code>; <code>{path}</code> in <code>label</code>, <code>short</code>, <code>mark</code>, or <code>keycap</code>; a <code>sparkline</code> without <code>bind</code>; a bad <code>scope</code>, <code>min</code>, or <code>max</code>; in a version=&quot;1&quot; or version=&quot;2&quot; document, with <code>(requires version=&quot;3&quot;)</code>: <code>{path}</code> in a tab&#39;s <code>label</code> or <code>short</code>, <code>row-gap</code>/<code>column-gap</code>, or the <code>wrap</code> values <code>truncate-start</code>/<code>truncate-middle</code> (an invalid <code>wrap</code> value lists the two only in a version=&quot;3&quot; document); <code>stick</code> other than <code>bottom</code>, or <code>stick</code> on a <code>scroll</code> with <code>axis=&quot;x&quot;</code>; a bad selector in a <code>&lt;keymap&gt;</code>&#39;s <code>when</code>, once, at the <code>&lt;keymap&gt;</code>; a <code>priority</code> that is not a non-negative integer; a <code>scale</code> that is not a plain identifier (version=&quot;3&quot;)</td></tr><tr><td><span id="v004"></span><code>V004</code></td><td>duplicate id; any <code>id</code> inside a container <code>each</code> template (version=&quot;2&quot;)</td></tr><tr><td><span id="v005"></span><code>V005</code></td><td>not well-formed XML; or not a Tuimark document: a root element other than <code>&lt;tui&gt;</code> (or the phase-0 alias <code>&lt;app&gt;</code>), or a <code>&lt;tui&gt;</code> with no <code>&lt;screen&gt;</code></td></tr><tr><td><span id="v006"></span><code>V006</code></td><td><code>style src</code> include cycle</td></tr><tr><td><span id="v007"></span><code>V007</code></td><td>control character or ANSI in text (strip + error)</td></tr><tr><td><span id="v008"></span><code>V008</code></td><td>native widget name not registered (v1.1+)</td></tr><tr><td><span id="v010"></span><code>V010</code></td><td><code>dock</code> and <code>fr</code> on the same axis</td></tr><tr><td><span id="v011"></span><code>V011</code></td><td><code>each</code> / <code>if</code> missing path; an <code>each</code> alias equal to an enclosing one (version=&quot;2&quot;)</td></tr><tr><td><span id="v012"></span><code>V012</code></td><td>list/input/button/modal without <code>id</code>; a <code>table</code>, <code>tabs</code>, or <code>tab</code> without <code>id</code> (version=&quot;2&quot;); a <code>scroll</code> with <code>stick</code> and no <code>id</code> (version=&quot;3&quot;)</td></tr><tr><td><span id="v013"></span><code>V013</code></td><td><code>&lt;text&gt;</code> has element children</td></tr><tr><td><span id="v014"></span><code>V014</code></td><td>retired: never reported since 0.4.1, when <code>version</code> became optional (a <code>&lt;tui&gt;</code> without it is <code>version=&quot;3&quot;</code>)</td></tr><tr><td><span id="v015"></span><code>V015</code></td><td>a <code>class:NAME</code> whose NAME is not <code>[a-z_][a-z0-9_-]*</code> or whose value is not <code>path</code> / <code>!path</code> (version=&quot;2&quot;)</td></tr><tr><td><span id="v016"></span><code>V016</code></td><td>0.2b structure (version=&quot;2&quot;): a <code>column</code> whose parent is not a <code>table</code>; a <code>table</code> child other than <code>column</code> and one <code>item</code>, or a second <code>item</code>; text directly in a <code>table</code>; a table <code>item</code> with children or text; an element inside a <code>column</code>; a <code>tab</code> whose parent is not a <code>tabs</code>; a <code>tabs</code> child other than <code>tab</code>, or text directly in a <code>tabs</code>; children or text in a <code>sparkline</code> or a <code>hints</code></td></tr><tr><td><span id="v017"></span><code>V017</code></td><td>a <code>table</code> without <code>each</code> or without a <code>column</code> child; a <code>tabs</code> without a <code>tab</code> child (version=&quot;2&quot;)</td></tr><tr><td><span id="v018"></span><code>V018</code></td><td><code>checked</code> on a <code>list</code>/<code>table</code> without both <code>each</code> and <code>key</code> (or on a list of static items); a <code>mark</code> that is not 1 or 2 columns wide; <code>mark</code> without <code>checked</code>; <code>on:change</code> on a <code>list</code> without <code>checked</code> (version=&quot;2&quot;)</td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout (<code>L…</code>) <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout (`L…`) {#layout}&quot;">​</a></h2><p>Reported while laying out a frame, so they depend on the size you render at.</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><span id="l001"></span><code>L001</code></td><td><code>fr</code> child of non-flex parent</td></tr><tr><td><span id="l002"></span><code>L002</code></td><td><code>%</code> child of <code>auto</code> parent on that axis</td></tr><tr><td><span id="l003"></span><code>L003</code></td><td>fixed + min exceeds parent (warning; clip); also a table whose visible columns&#39; cell and <code>%</code> widths and <code>auto</code>/<code>fr</code> min-widths, plus the gaps, exceed its width; in a version=&quot;3&quot; document, evaluated on the columns left once <code>priority</code> has hidden some</td></tr><tr><td><span id="l004"></span><code>L004</code></td><td>modal is not last child of screen</td></tr><tr><td><span id="l005"></span><code>L005</code></td><td>more than one bottom-docked status (warning)</td></tr><tr><td><span id="l006"></span><code>L006</code></td><td>a scroll/list/table/overflow: scroll viewport can never show part of its content (warning); for a table, a body viewport of 0 rows while it has rows</td></tr><tr><td><span id="l007"></span><code>L007</code></td><td>in a <code>layout: grid</code> container, a child with a document-written <code>width</code>, <code>min-width</code>, <code>max-width</code>, or <code>flex</code> (ignored), or an <code>fr</code> or <code>%</code> <code>height</code> (treated as <code>auto</code>) (warning; version=&quot;2&quot;)</td></tr><tr><td><span id="l008"></span><code>L008</code></td><td>in a <code>version=&quot;3&quot;</code> document, a painted <code>text</code> (not <code>visibility: hidden</code>, not a table cell/tab label/hint item) that loses columns (a document-unwritten <code>nowrap</code> line wider than its content box) or lines (more lines than its content box has rows, with <code>overflow: hidden</code> not document-written) without saying so (warning; version=&quot;3&quot;)</td></tr><tr><td><span id="l009"></span><code>L009</code></td><td>in a <code>version=&quot;3&quot;</code> document, a container that cuts a child, in flow or docked, on an axis it does not itself scroll, when <code>overflow: hidden</code> is not document-written on it; not for a <code>list</code>, a <code>table</code>, or a <code>hints</code>, for a node <code>L003</code> already reports, or for a child <code>L006</code> already reports (warning; version=&quot;3&quot;)</td></tr></tbody></table><h2 id="bind" tabindex="-1">Bind (<code>B…</code>) <a class="header-anchor" href="#bind" aria-label="Permalink to &quot;Bind (`B…`) {#bind}&quot;">​</a></h2><p>Reported while resolving paths against the JSON data. <code>validate</code> checks them only when you pass <code>--data</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><span id="b001"></span><code>B001</code></td><td><code>each</code> path is missing or not an array (a <code>list</code>, or a <code>col</code>/<code>row</code>/<code>box</code>/<code>table</code> in version=&quot;2&quot;)</td></tr><tr><td><span id="b002"></span><code>B002</code></td><td><code>if</code> path missing; also a <code>class:NAME</code> guard path</td></tr><tr><td><span id="b003"></span><code>B003</code></td><td>bind path missing (<code>--strict</code> upgrades to error); also a table&#39;s <code>bind</code>, <code>placeholder</code>, row <code>key</code>, and column cell templates, reported once per template and path whatever rows are visible; a <code>tabs</code> or <code>sparkline</code> <code>bind</code>; a missing path in a tab&#39;s <code>label</code> or <code>short</code> (version=&quot;3&quot;)</td></tr><tr><td><span id="b004"></span><code>B004</code></td><td>action not in catalog</td></tr><tr><td><span id="b005"></span><code>B005</code></td><td>keymap <code>to</code>/<code>when</code> id missing; a <code>tab focus=</code> that names no node, a node inside a list item, or a node outside that tab (version=&quot;2&quot;); a <code>modal focus=</code> that names no node, a node outside the modal, or a node inside a list item or an each template (version=&quot;3&quot;); a <code>&lt;keymap&gt;</code>&#39;s <code>when</code> whose id names no node, or a node inside a list item or an each template, once, at the <code>&lt;keymap&gt;</code> (version=&quot;3&quot;)</td></tr><tr><td><span id="b006"></span><code>B006</code></td><td><code>list</code> + <code>each</code> without <code>key</code> (warning); also <code>table</code> + <code>each</code> without <code>key</code></td></tr><tr><td><span id="b007"></span><code>B007</code></td><td>a built-in action whose target is known without data to be incompatible (from <code>to=</code>, or a <code>when</code> that is exactly <code>#id:focus</code>); static, error (version=&quot;2&quot;); evaluated against each row&#39;s effective <code>when</code> (version=&quot;3&quot;, <code>&lt;keymap when&gt;</code>)</td></tr><tr><td><span id="b008"></span><code>B008</code></td><td>the value at a <code>checked</code> path is present and not an array (error; version=&quot;2&quot;)</td></tr><tr><td><span id="b009"></span><code>B009</code></td><td>the value at a <code>sparkline</code> <code>bind</code> is present and not an array, or holds an element that is neither a number nor <code>null</code> (warning; version=&quot;2&quot;)</td></tr><tr><td><span id="b010"></span><code>B010</code></td><td>the value at a <code>tabs</code> <code>bind</code> is present, not <code>null</code>, and not the id of a visible tab; the first visible tab is active and the store is not written (warning; version=&quot;2&quot;)</td></tr></tbody></table>',11)])])}const m=o(a,[["render",n]]);export{p as __pageData,m as default};
